{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.category_date_wise_data AS WITH mp_sor as ( SELECT TO_DATE(order_created_date, \'YYYYMMDD\') AS date, UPPER( IFF( UPPER(REPLACE(style_, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(style_, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(style_, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(style_, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, style_ sku_group, \'Marketplace\' AS channel, \'SOR\' AS mode, SUM(TRY_TO_NUMBER(REPLACE(sales, \',\', \'\'))) AS qty, SUM(TRY_TO_NUMBER(REPLACE(revenue, \',\', \'\'))) AS gross_sales_value FROM snitch_db.maplemonk.mp_sor_sales_myntra WHERE order_created_date>=20260301 and order_created_date<=20260331 GROUP BY 1,2,3,4 UNION ALL SELECT TO_DATE(order_date_key, \'YYYYMMDD\') AS date, UPPER( IFF( UPPER(REPLACE(style_, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(style_, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(style_, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(style_, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, style_ sku_group, \'Marketplace\' AS channel, \'SOR\' AS mode, SUM(TRY_TO_NUMBER(REPLACE(units, \',\', \'\'))) AS qty, SUM( TRY_TO_NUMBER(REPLACE(sp_per_unit_, \',\', \'\')) * TRY_TO_NUMBER(REPLACE(units, \',\', \'\')) ) AS gross_sales_value FROM snitch_db.maplemonk.mp_sor_sales_flipkart GROUP BY 1,2,3,4 ), sor as ( select date,sku_group_clean,sku_group,channel,mode, qty, gross_sales_value from mp_sor ), base_sales_1 AS ( SELECT date, UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, sku_group, CASE WHEN type = \'Shopify\' THEN \'Shopify\' WHEN type = \'Marketplace\' THEN \'Marketplace\' WHEN type = \'Store\' THEN \'Offline\' END AS channel, \'B2C\' Mode, SUM(gross_sales::INT) AS gross_sales_value, SUM(gross_quantity::INT) AS qty FROM snitch_db.maplemonk.horizontal_sales_categories where date >=\'2026-03-01\' GROUP BY 1,2,3,4 ) , base_Sales as ( select date,sku_group_clean,sku_group,channel ,sum(qty) qty,sum(gross_sales_value) gross_sales_value from ( select date,sku_group_clean,sku_group,channel,mode,qty,gross_sales_value from base_sales_1 union all select date,sku_group_clean,sku_group,channel,mode,qty,gross_sales_value from sor ) group by 1,2,3,4 ), mrp_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(sku, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(sku, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(sku, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(sku, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(sku, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, AVG(MRP) AS MRP FROM snitch_db.maplemonk.logic_final_item_master WHERE BRAND = \'SNITCH\' GROUP BY 1 ), meta_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END), MIN(a.l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END), MIN(a.category) ) AS category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta1 END), MIN(a.meta1) ) AS meta1, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta2 END), MIN(a.meta2) ) AS meta2, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta3 END), MIN(a.meta3) ) AS meta3, MAX(cogs) AS cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku a GROUP BY 1 ), temp AS ( WITH a AS ( SELECT LEFT(value:sku::STRING, LENGTH(value:sku::STRING) - POSITION(\'-\' IN REVERSE(value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => PARSE_JSON(variants)) AS value ) SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean FROM a ), as_of AS ( SELECT CURRENT_DATE() AS as_of_date ), inv_current_by_sku AS ( SELECT UPPER( IFF( UPPER(REPLACE(s.sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(s.sku_group, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(s.sku_group, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(s.sku_group, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(s.sku_group, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, SUM(COALESCE(qty_available, 0) + COALESCE(qty_offline_available, 0) + COALESCE(qty_jit, 0)) AS inv_current, SUM(COALESCE(qty_available, 0)) AS online_inv_current, SUM(COALESCE(qty_offline_available, 0) + COALESCE(qty_jit, 0)) AS offline_inv_current, SUM(qty_bad_inventory) AS bad_inv, SUM(qty_blocked) AS blocked_inv FROM snitch_db.maplemonk.cogs_daily_snapshot s WHERE s.date = CURRENT_DATE() - 1 GROUP BY 1 ), inward_lots AS ( SELECT UPPER( IFF( UPPER(REPLACE(p.\"Item Type skuCode\", \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(p.\"Item Type skuCode\", \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(p.\"Item Type skuCode\", \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(p.\"Item Type skuCode\", \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(p.\"Item Type skuCode\", \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, p.\"PUTAWAY_UPDATED\"::DATE AS inward_date, SUM(p.\"PUTAWAY_COMPLETED_QUANTITY\") AS inward_qty FROM snitch_db.maplemonk.putaway_tracking p WHERE LOWER(p.final_type) = \'new inward\' GROUP BY 1,2 ), inward_lots_fifo AS ( SELECT il.*, SUM(inward_qty) OVER ( PARTITION BY sku_group_clean ORDER BY inward_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_inward_qty, SUM(inward_qty) OVER ( PARTITION BY sku_group_clean ORDER BY inward_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) - inward_qty AS cum_inward_qty_prev FROM inward_lots il ), inward_total AS ( SELECT sku_group_clean, SUM(inward_qty) AS total_inward_qty FROM inward_lots GROUP BY 1 ), fifo_remaining_by_lot AS ( SELECT f.sku_group_clean, f.inward_date, f.inward_qty, ic.inv_current, ic.online_inv_current, ic.offline_inv_current, ic.bad_inv, ic.blocked_inv, it.total_inward_qty, GREATEST( COALESCE(it.total_inward_qty, 0) - COALESCE(ic.inv_current, 0), 0 ) AS consumed_qty, GREATEST( LEAST( f.inward_qty, GREATEST( COALESCE(it.total_inward_qty, 0) - COALESCE(ic.inv_current, 0), 0 ) - f.cum_inward_qty_prev ), 0 ) AS consumed_in_lot, GREATEST( f.inward_qty - GREATEST( LEAST( f.inward_qty, GREATEST( COALESCE(it.total_inward_qty, 0) - COALESCE(ic.inv_current, 0), 0 ) - f.cum_inward_qty_prev ), 0 ), 0 ) AS remaining_qty, DATEDIFF(\'day\', f.inward_date, CURRENT_DATE()) AS lot_age_days FROM inward_lots_fifo f LEFT JOIN inv_current_by_sku ic ON f.sku_group_clean = ic.sku_group_clean LEFT JOIN inward_total it ON f.sku_group_clean = it.sku_group_clean ), inv_ageing_fifo AS ( SELECT sku_group_clean, MAX(inv_current) AS inv_current, MAX(online_inv_current) AS online_inv_current, MAX(offline_inv_current) AS offline_inv_current, MAX(bad_inv) AS bad_inv, MAX(blocked_inv) AS blocked_inv, SUM(remaining_qty) AS remaining_qty_total, CASE WHEN SUM(remaining_qty) = 0 THEN 0 ELSE SUM(remaining_qty * lot_age_days) / NULLIF(SUM(remaining_qty), 0) END AS weighted_age_days FROM fifo_remaining_by_lot GROUP BY 1 ), inv_ageing AS ( SELECT sku_group_clean, inv_current, remaining_qty_total, weighted_age_days, online_inv_current, offline_inv_current, bad_inv, blocked_inv, CASE WHEN weighted_age_days <= 30 THEN \'0-30\' WHEN weighted_age_days <= 60 THEN \'30-60\' WHEN weighted_age_days <= 90 THEN \'60-90\' WHEN weighted_age_days <= 120 THEN \'90-120\' WHEN weighted_age_days <= 180 THEN \'120-180\' WHEN weighted_age_days <= 270 THEN \'180-270\' WHEN weighted_age_days <= 360 THEN \'270-360\' ELSE \'360+\' END AS inventory_ageing_bucket FROM inv_ageing_fifo ) SELECT bs.date, bs.channel, ia.inventory_ageing_bucket, sku_group, mm.l1_category AS l1_category, mm.category AS category, mm.meta1 AS meta1, mm.meta2 AS meta2, mm.meta3 AS meta3, MAX(mm.cogs) AS cogs, AVG(mrp.MRP) AS mrp, SUM(bs.gross_sales_value) AS gross_sales_value, SUM(bs.qty * mrp.MRP) AS mrp_value, SUM(bs.qty) AS qty, SUM(bs.qty * mm.cogs) AS cogs_sold FROM base_sales bs FULL OUTER JOIN inv_ageing ia USING (sku_group_clean) LEFT JOIN mrp_map mrp USING (sku_group_clean) LEFT JOIN meta_map mm USING (sku_group_clean) WHERE bs.date >= \'2026-04-01\' GROUP BY 1,2,3,4,5,6,7,8,9;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
